<?php
declare(strict_types=1);
namespace Bitrix\Main\Config {class Option {public static array $values=[];static function get($module,$key,$default=''){return self::$values[$key]??$default;}static function set($module,$key,$value){self::$values[$key]=$value;}}}
namespace Bitrix\Main {class ModuleManager {static function isModuleInstalled($id){return $id==='prospektweb.calc';}}class Loader {static function includeModule($id){return true;}}class Application {static function getConnection(){return $GLOBALS['db'];}}}
namespace {
class Rows {function __construct(private array $rows){}function fetch(){return array_shift($this->rows);}}
class FakeDb {public int $released=0;function getSqlHelper(){return new class {function forSql($s){return addslashes($s);}};}function query($s){if(str_contains($s,'GET_LOCK'))return new Rows([['ACQUIRED'=>1]]);if(str_contains($s,'RELEASE_LOCK')){$this->released++;return new Rows([]);}if(str_contains($s,'FROM b_option'))return new Rows([['MODULE_ID'=>'prospektweb.frontcalc','NAME'=>'OFFERS_IBLOCK_ID','VALUE'=>'15','SITE_ID'=>null],['MODULE_ID'=>'prospektweb.frontcalc','NAME'=>'PRODUCTS_IBLOCK_ID','VALUE'=>'14','SITE_ID'=>null]]);if(str_contains($s,'FROM b_iblock WHERE'))return new Rows([['ID'=>14],['ID'=>15]]);if(str_contains($s,'FROM b_catalog_iblock'))return new Rows([['IBLOCK_ID'=>15,'PRODUCT_IBLOCK_ID'=>14,'SKU_PROPERTY_ID'=>279]]);throw new RuntimeException('Unexpected query');}}
class CIBlockProperty {static array $rows=[];static int $next=100;public string $LAST_ERROR='';static function GetList($sort,$filter){return new Rows(array_values(array_filter(self::$rows,fn($r)=>$r['IBLOCK_ID']===$filter['IBLOCK_ID'])));}static function GetUserType($type){return [];}function Add($fields){$id=self::$next++;self::$rows[$id]=$fields+['ID'=>$id];return $id;}function Update($id,$fields){self::$rows[$id]=array_replace(self::$rows[$id],$fields);return true;}}
class CIBlockPropertyEnum {static array $rows=[];static int $next=200;static function GetList($sort,$filter){return new Rows(array_values(array_filter(self::$rows,fn($r)=>$r['PROPERTY_ID']==$filter['PROPERTY_ID'])));}function Add($f){$id=self::$next++;self::$rows[$id]=$f+['ID'=>$id];return $id;}function Update($id,$fields){self::$rows[$id]=array_replace(self::$rows[$id],$fields);return true;}}
class CIBlockElement {static int $valueCount=1;static function GetList(...$args){return self::$valueCount;}}
require_once __DIR__.'/../lib/Catalog/TradePropertyService.php';
$GLOBALS['db']=new FakeDb();$_SERVER['DOCUMENT_ROOT']=sys_get_temp_dir().'/pw-trade-test-'.bin2hex(random_bytes(5));
$manifest=['contract'=>'prospektweb.calc.trade-properties/v1','revision'=>1,'properties'=>[['role'=>'products','fields'=>['CODE'=>'CALC_TEST','NAME'=>'QA','PROPERTY_TYPE'=>'L','USER_TYPE'=>'','MULTIPLE'=>'N','ACTIVE'=>'Y','SORT'=>100],'enums'=>[['VALUE'=>'Да','XML_ID'=>'Y','SORT'=>'100','DEF'=>'N']],'description'=>'QA']]];
$count=0;function ok($v,$m){global$count;$count++;if(!$v)throw new RuntimeException($m);}
$service=new \Prospektweb\Calc\Catalog\TradePropertyService($manifest);
$before=$service->inspect();ok(!$before['initialized']&&$before['summary']['create']===1,'inspect only');ok(!CIBlockProperty::$rows&&!\Bitrix\Main\Config\Option::$values,'no read mutations');
foreach([['hash'=>str_repeat('0',64),'confirm'=>true],['hash'=>$before['hash'],'confirm'=>false]]as$case){$denied=false;try{$service->apply($case['hash'],$case['confirm'],1);}catch(InvalidArgumentException|RuntimeException$e){$denied=true;}ok($denied&&!CIBlockProperty::$rows,'CAS and confirmation reject before writes');}
$applied=$service->apply($before['hash'],true,1);ok($applied['plan']['initialized']&&$applied['plan']['summary']['ready']===1,'create and authoritative readback');$id=$applied['applied'][0]['id'];$enumId=array_key_first(CIBlockPropertyEnum::$rows);$files=glob($_SERVER['DOCUMENT_ROOT'].'/bitrix/backup/prospektweb.calc/trade-properties/*.json');ok(count($files)===1&&is_file($files[0]),'backup persisted before schema write');
$repeat=$service->apply($applied['plan']['hash'],true,1);ok(!$repeat['applied'],'repeated action idempotent');
CIBlockProperty::$rows[$id]['NAME']='Changed';CIBlockPropertyEnum::$rows[$enumId]['VALUE']='Changed';$fix=$service->apply($service->inspect()['hash'],true,1);ok($fix['applied'][0]['id']===$id&&CIBlockProperty::$rows[$id]['NAME']==='QA','same property ID metadata repair');ok(array_key_first(CIBlockPropertyEnum::$rows)===$enumId&&CIBlockPropertyEnum::$rows[$enumId]['VALUE']==='Да','same enum ID/code repair');
CIBlockProperty::$rows[$id]['CODE']='RENAMED';$renamed=$service->apply($service->inspect()['hash'],true,1);ok(CIBlockProperty::$rows[$id]['CODE']==='CALC_TEST'&&count(CIBlockProperty::$rows)===1,'registry restores renamed property');
CIBlockProperty::$rows[$id]['PROPERTY_TYPE']='S';$blocked=$service->apply($service->inspect()['hash'],true,1);ok($blocked['plan']['summary']['blocked']===1&&!$blocked['applied']&&CIBlockProperty::$rows[$id]['PROPERTY_TYPE']==='S','destructive type change remains blocked');
CIBlockElement::$valueCount=0;$emptyType=$service->apply($service->inspect()['hash'],true,1);ok($emptyType['plan']['summary']['ready']===1&&count(CIBlockPropertyEnum::$rows)===1&&array_key_first(CIBlockPropertyEnum::$rows)===$enumId,'empty type restoration reads existing enum IDs even while type is temporarily S');CIBlockElement::$valueCount=1;
CIBlockProperty::$rows[$id]['PROPERTY_TYPE']='L';unset(CIBlockProperty::$rows[$id]);$restored=$service->apply($service->inspect()['hash'],true,1);ok($restored['plan']['initialized']&&$restored['plan']['summary']['ready']===1&&$restored['applied'][0]['id']!==$id,'deleted property recreated under update action');
ok($GLOBALS['db']->released===8,'lock released on success and conflict');
foreach(glob($_SERVER['DOCUMENT_ROOT'].'/bitrix/backup/prospektweb.calc/trade-properties/*.json')as$file)unlink($file);foreach(['/bitrix/backup/prospektweb.calc/trade-properties','/bitrix/backup/prospektweb.calc','/bitrix/backup','/bitrix','']as$part)rmdir($_SERVER['DOCUMENT_ROOT'].$part);
echo $count." native-adapter trade property checks PASS\n";
}
